// The vendored @chatgoose/hotkeys drift gate: the package is generated by the
// hub's scripts/vendor-hotkeys.mjs and must be byte-identical to its manifest —
// and, at release, to the desktop app's copy (same sha256, same source commit).

import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';
import { HOTKEY_SCHEME_VERSION, HOTKEYS } from '@chatgoose/hotkeys';

import manifest from '../vendor/chatgoose-hotkeys/chatgoose-hotkeys.vendor.json';

const vendorDir = fileURLToPath(new URL('../vendor/chatgoose-hotkeys/', import.meta.url));

describe('vendored @chatgoose/hotkeys', () => {
  it('matches its manifest file by file', () => {
    for (const [file, hash] of Object.entries(manifest.files)) {
      const actual = createHash('sha256').update(readFileSync(`${vendorDir}${file}`)).digest('hex');
      expect(actual, file).toBe(hash);
    }
    expect(createHash('sha256').update(JSON.stringify(manifest.files)).digest('hex')).toBe(manifest.sha256);
  });

  it('was vendored from a clean hub commit and loads at runtime', () => {
    expect(manifest.sourceCommit).toMatch(/^[0-9a-f]{40}$/);
    expect(manifest.schemeVersion).toBe(HOTKEY_SCHEME_VERSION);
    expect(HOTKEYS.length).toBeGreaterThan(0);
  });
});
